        brain=(f'/submittals/{sid}/brain/review/{rid}' if rid else f'/submittals/{sid}/brain')
        badge="#166534" if status in ("APPROVED","APPROVED_AS_NOTED") else ("#b91c1c" if status in ("REJECTED","REVISE_RESUBMIT") else "#a16207")
