# Override GET route endpoints while leaving POST auth handlers untouched.
def _bc630_install_auth_design():
    changed = []
    for route in app.routes:
        path = getattr(route, "path", "")
        methods = set(getattr(route, "methods", set()) or set())
        if "GET" not in methods:
            continue
        if path == "/login":
            def bc630_login_get():
                return _BC200_HTMLResponse(_bc630_auth_html("login"))
            route.endpoint = bc630_login_get
            if hasattr(route, "dependant"):
                try:
                    route.dependant.call = bc630_login_get
                except Exception:
                    pass
            changed.append("login")
        elif path in ("/signup","/register","/create-account"):
            def bc630_signup_get():
                return _BC200_HTMLResponse(_bc630_auth_html("signup"))
            route.endpoint = bc630_signup_get
            if hasattr(route, "dependant"):
                try:
                    route.dependant.call = bc630_signup_get
                except Exception:
                    pass
            changed.append(path)
    return changed

_BC630_AUTH_ROUTES = _bc630_install_auth_design()

