def _bc652_strip_650_brand_wrap(html):
    if not isinstance(html, str):
        return html
    # Remove 6.5.x's injected top brand block so the working app's original
    # background/layout is restored.
    html = re.sub(
        r'<div id="bc650-brand-wrap".*?</div>\s*</div>',
        '',
        html,
        count=1,
        flags=re.S
    )
    # Also remove its styling append if present.
    html = re.sub(
        r'<style>\s*\.old-logo,\.legacy-logo,\.brand-logo-old.*?</style>',
        '',
        html,
        count=1,
        flags=re.S
    )
    return html

def _bc652_app_logo_overlay():
    return """<div id="bc652-app-logo" style="
      position:fixed;left:18px;top:12px;z-index:9998;width:255px;
      pointer-events:none">
      <img src="/brand/buildcommand-main-logo"
           alt="BuildCommand"
           style="display:block;width:100%;height:auto;object-fit:contain">
    </div>
    <style>
      #bc652-app-logo{filter:drop-shadow(0 2px 7px rgba(0,0,0,.35))}
      @media(max-width:900px){#bc652-app-logo{width:190px;left:10px;top:8px}}
    </style>"""

# Outermost middleware: fixes visuals after prior branding middleware has run.
@app.middleware("http")
async def bc652_background_restore(request, call_next):
    path = request.url.path or "/"
    method = request.method.upper()

    # Serve the approved original sign-in visual directly.
    if method == "GET" and path == "/login":
        return _BC200_HTMLResponse(_bc652_login_html())

    response = await call_next(request)

    # Do not touch auth, billing, Stripe, health or asset responses.
    excluded = (
        path in ("/login","/signup","/register","/logout","/choose-plan","/payment-required")
        or path.startswith("/billing/")
        or path.startswith("/health/")
        or path.startswith("/brand/")
        or path.startswith("/api/")
    )
    if excluded:
        return response

    ctype = str(response.headers.get("content-type") or "").lower()
    if "text/html" not in ctype:
        return response

    try:
        chunks = []
        async for chunk in response.body_iterator:
            chunks.append(chunk)
        body = b"".join(chunks).decode("utf-8", errors="replace")
        body = _bc652_strip_650_brand_wrap(body)

        # Preserve original construction-app background and layout;
        # only overlay the approved main logo.
        body_pos = body.lower().find("<body")
        if body_pos >= 0:
            body_end = body.find(">", body_pos)
            if body_end >= 0 and "bc652-app-logo" not in body:
                body = body[:body_end+1] + _bc652_app_logo_overlay() + body[body_end+1:]

        headers = dict(response.headers)
        headers.pop("content-length", None)
        return _BC200_HTMLResponse(body, status_code=response.status_code, headers=headers)
    except Exception:
        return response

